CREATE OR REPLACE FUNCTION public.current_user_org_ids() RETURNS SETOF uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $function$ SELECT o.id FROM public.organizations o WHERE EXISTS (SELECT 1 FROM public.user_roles ur JOIN public.roles r ON r.id = ur.role_id WHERE ur.user_id = auth.uid() AND r.name = 'SUPER_ADMIN') UNION SELECT ur.organization_id FROM public.user_roles ur WHERE ur.user_id = auth.uid(); $function$;